SELECT (SELECT COUNT(*) FROM users) AS user_cnt,
       (SELECT COUNT(DISTINCT o2.user_id) FROM refunds r JOIN orders o2 ON o2.id = r.order_id) AS refund_user_cnt,
       (SELECT COUNT(DISTINCT o.user_id) FROM orders o JOIN payments p ON p.order_id = o.id) AS paid_user_cnt;

SELECT new_customers, total_customers, ROUND(new_customers / total_customers, 4) AS new_customer_ratio
FROM (
  SELECT
    (SELECT COUNT(*) FROM (
        SELECT user_id FROM orders GROUP BY user_id
        HAVING MIN(created_at) >= '2026-09-01' AND MIN(created_at) < '2026-10-01'
     ) t) AS new_customers,
    (SELECT COUNT(DISTINCT user_id) FROM orders
      WHERE created_at >= '2026-09-01' AND created_at < '2026-10-01') AS total_customers
) x;

